  "pr.badge.ownAll": { en: "You own everything", es: "Todo es tuyo", zh: "一切归你所有", yue: "一切歸你所有", ru: "Всё принадлежит вам", yi: "איר פֿאַרמאָגט אַלץ", bn: "সবকিছুর মালিক আপনি", ko: "모든 것을 소유", ht: "Ou posede tout", it: "Tutto è tuo", ar: "أنت تملك كل شيء", pl: "Wszystko należy do ciebie" },
