  "pr.tag.starter": { en: "Small budgets welcome", es: "Presupuestos pequeños bienvenidos", zh: "小预算也欢迎", yue: "細預算都歡迎", ru: "Рады небольшим бюджетам", yi: "קליינע בודזשעטן זײַנען ווילקאָם", bn: "ছোট বাজেট স্বাগত", ko: "적은 예산도 환영", ht: "Ti bidjè byenveni", it: "Piccoli budget benvenuti", ar: "الميزانيات الصغيرة مرحّب بها", pl: "Małe budżety mile widziane" },
