  "pr.tag.elite": { en: "Scaling up", es: "Para escalar", zh: "扩大规模", yue: "擴大規模", ru: "Для масштабирования", yi: "סקאַלירן אַרויף", bn: "স্কেল আপ", ko: "규모 확장", ht: "Ap grandi", it: "In fase di crescita", ar: "التوسّع", pl: "Skalowanie" },
  "pr.desc.starter": { en: "A clean, fast site to get your business online this week.", es: "Un sitio limpio y rápido para poner tu negocio en línea esta semana.", zh: "一个简洁、快速的网站，本周就让你的生意上线。", yue: "一個簡潔、快速嘅網站，今個星期就令你盤生意上線。", ru: "Чистый и быстрый сайт, чтобы вывести бизнес в сеть уже на этой неделе.", yi: "אַ ריינער, גיכער וועבזייטל צו ברענגען אײַער געשעפֿט אויף דער אינטערנעץ די וואָך.", bn: "একটি পরিচ্ছন্ন, দ্রুত সাইট, এই সপ্তাহেই আপনার ব্যবসা অনলাইনে আনতে।", ko: "이번 주에 비즈니스를 온라인에 올리는 깔끔하고 빠른 사이트.", ht: "Yon sit pwòp, rapid pou mete biznis ou anliy semèn sa a.", it: "Un sito pulito e veloce per portare la tua attività online questa settimana.", ar: "موقع نظيف وسريع لإطلاق عملك على الإنترنت هذا الأسبوع.", pl: "Czysta, szybka strona, by wprowadzić firmę online w tym tygodniu." },
  "pr.desc.growth": { en: "For businesses ready to compete and win more customers.", es: "Para negocios listos para competir y ganar más clientes.", zh: "为准备好竞争、赢得更多客户的企业而设。", yue: "為準備好競爭、贏得更多客戶嘅企業而設。", ru: "Для бизнеса, готового конкурировать и привлекать больше клиентов.", yi: "פֿאַר געשעפֿטן גרייט צו קאָנקורירן און געווינען מער קונים.", bn: "প্রতিযোগিতায় নামতে ও আরও গ্রাহক জিততে প্রস্তুত ব্যবসার জন্য।", ko: "경쟁하고 더 많은 고객을 얻을 준비가 된 비즈니스를 위해.", ht: "Pou biznis ki pare pou konpetisyone epi genyen plis kliyan.", it: "Per aziende pronte a competere e conquistare più clienti.", ar: "للأعمال المستعدة للمنافسة وكسب مزيد من العملاء.", pl: "Dla firm gotowych konkurować i zdobywać więcej klientów." },
  "pr.desc.elite": { en: "A full custom build with commerce, integrations, and strategy.", es: "Una construcción totalmente a medida con comercio, integraciones y estrategia.", zh: "一次完全定制的构建，涵盖电商、集成与策略。", yue: "一次完全訂造嘅構建，涵蓋電商、整合同策略。", ru: "Полностью индивидуальная сборка с коммерцией, интеграциями и стратегией.", yi: "אַ פֿולער מנהג בוי מיט מסחר, אינטעגראַציעס, און סטראַטעגיע.", bn: "কমার্স, ইন্টিগ্রেশন ও কৌশলসহ সম্পূর্ণ কাস্টম নির্মাণ।", ko: "커머스, 통합, 전략을 포함한 완전 맞춤 제작.", ht: "Yon konstriksyon konplè sou mezi ak komès, entegrasyon, ak estrateji.", it: "Una realizzazione completamente su misura con e-commerce, integrazioni e strategia.", ar: "بناء مخصص كامل مع تجارة إلكترونية وتكاملات واستراتيجية.", pl: "W pełni indywidualna realizacja z e-commerce, integracjami i strategią." },
  "pr.from": { en: "from", es: "desde", zh: "起", yue: "起", ru: "от", yi: "פֿון", bn: "থেকে", ko: "부터", ht: "apati", it: "da", ar: "من", pl: "od" },
  "pr.perMo": { en: "/mo", es: "/mes", zh: "/月", yue: "/月", ru: "/мес", yi: "/חודש", bn: "/মাস", ko: "/월", ht: "/mwa", it: "/mese", ar: "/شهر", pl: "/mies" },
  "pr.flat": { en: "flat", es: "fijo", zh: "统一价", yue: "統一價", ru: "фикс.", yi: "פֿלאַך", bn: "নির্দিষ্ট", ko: "정액", ht: "fiks", it: "fisso", ar: "ثابت", pl: "stała" },
