  "ct.f.send": { en: "Send the brief", es: "Enviar el brief", zh: "发送简报", yue: "發送簡報", ru: "Отправить бриф", yi: "שיק דעם בריף", bn: "ব্রিফ পাঠান", ko: "브리프 보내기", ht: "Voye rezime a", it: "Invia il brief", ar: "أرسل الملخّص", pl: "Wyślij brief" },
  "ct.f.note": { en: "We reply within 24 hours · or email hello@webdevny.com", es: "Respondemos en 24 horas · o escribe a hello@webdevny.com", zh: "我们 24 小时内回复 · 或发邮件至 hello@webdevny.com", yue: "我哋 24 小時內回覆 · 或電郵至 hello@webdevny.com", ru: "Отвечаем в течение 24 часов · или пишите на hello@webdevny.com", yi: "מיר ענטפֿערן אין 24 שעה · אָדער בליץ-פּאָסט hello@webdevny.com", bn: "আমরা ২৪ ঘণ্টার মধ্যে উত্তর দিই · অথবা ইমেইল করুন hello@webdevny.com", ko: "24시간 내에 답장드립니다 · 또는 hello@webdevny.com 으로 이메일", ht: "Nou reponn nan 24 èdtan · oswa imèl hello@webdevny.com", it: "Rispondiamo entro 24 ore · oppure scrivi a hello@webdevny.com", ar: "نردّ خلال 24 ساعة · أو راسلنا على hello@webdevny.com", pl: "Odpowiadamy w ciągu 24 godzin · lub napisz na hello@webdevny.com" },
  "ct.err.slow": { en: "Please take a moment, then send again.", es: "Tómate un momento y envíalo de nuevo.", zh: "请稍等片刻，然后再次发送。", yue: "請稍等一陣，然後再次發送。", ru: "Пожалуйста, подождите немного и отправьте снова.", yi: "ביטע נעמט אַ מאָמענט, און שיקט נאָך אַ מאָל.", bn: "একটু সময় নিন, তারপর আবার পাঠান।", ko: "잠시 후 다시 보내주세요.", ht: "Tanpri pran yon moman, epi voye ankò.", it: "Prenditi un momento, poi invia di nuovo.", ar: "خذ لحظة ثم أرسل مرة أخرى.", pl: "Poczekaj chwilę i wyślij ponownie." },
  "ct.err.rate": { en: "You just sent a message. Please wait a moment before sending another.", es: "Acabas de enviar un mensaje. Espera un momento antes de enviar otro.", zh: "你刚发送了一条消息。请稍候再发送另一条。", yue: "你啱啱發送咗一條訊息。請稍候再發送另一條。", ru: "Вы только что отправили сообщение. Подождите немного перед следующим.", yi: "איר האָט נאָר וואָס געשיקט אַ מעלדונג. ביטע וואַרט אַ מאָמענט איידער איר שיקט נאָך איינע.", bn: "আপনি এইমাত্র একটি বার্তা পাঠিয়েছেন। আরেকটি পাঠানোর আগে একটু অপেক্ষা করুন।", ko: "방금 메시지를 보냈습니다. 다음 메시지를 보내기 전에 잠시 기다려 주세요.", ht: "Ou fèk voye yon mesaj. Tanpri tann yon moman anvan ou voye yon lòt.", it: "Hai appena inviato un messaggio. Attendi un momento prima di inviarne un altro.", ar: "لقد أرسلت رسالة للتو. انتظر لحظة قبل إرسال أخرى.", pl: "Właśnie wysłałeś wiadomość. Poczekaj chwilę przed wysłaniem kolejnej." },
  "ct.err.generic": { en: "Something went wrong. Please email us directly.", es: "Algo salió mal. Escríbenos directamente.", zh: "出了点问题。请直接给我们发邮件。", yue: "出咗啲問題。請直接畀電郵我哋。", ru: "Что-то пошло не так. Напишите нам напрямую.", yi: "עפּעס איז געגאַנגען אומריכטיק. ביטע בליץ-פּאָסט אונדז דירעקט.", bn: "কিছু একটা ভুল হয়েছে। সরাসরি আমাদের ইমেইল করুন।", ko: "문제가 발생했습니다. 직접 이메일을 보내주세요.", ht: "Yon bagay pa mache. Tanpri imèl nou dirèkteman.", it: "Qualcosa è andato storto. Scrivici direttamente.", ar: "حدث خطأ ما. راسلنا مباشرة.", pl: "Coś poszło nie tak. Napisz do nas bezpośrednio." },
  "ct.err.network": { en: "Network error. Please email hello@webdevny.com directly.", es: "Error de red. Escribe directamente a hello@webdevny.com.", zh: "网络错误。请直接发邮件至 hello@webdevny.com。", yue: "網絡錯誤。請直接電郵至 hello@webdevny.com。", ru: "Ошибка сети. Напишите напрямую на hello@webdevny.com.", yi: "נעץ פֿעלער. ביטע בליץ-פּאָסט hello@webdevny.com דירעקט.", bn: "নেটওয়ার্ক ত্রুটি। সরাসরি hello@webdevny.com এ ইমেইল করুন।", ko: "네트워크 오류입니다. hello@webdevny.com 으로 직접 이메일을 보내주세요.", ht: "Erè rezo. Tanpri imèl hello@webdevny.com dirèkteman.", it: "Errore di rete. Scrivi direttamente a hello@webdevny.com.", ar: "خطأ في الشبكة. راسلنا مباشرة على hello@webdevny.com.", pl: "Błąd sieci. Napisz bezpośrednio na hello@webdevny.com." },
  "ct.quote.carried": { en: "Your estimate, carried over", es: "Tu presupuesto, trasladado", zh: "你的估价，已带入", yue: "你嘅估價，已帶入", ru: "Ваша смета перенесена", yi: "אײַער אָפּשאַצונג, אַריבערגעטראָגן", bn: "আপনার প্রাক্কলন, নিয়ে আসা হয়েছে", ko: "이어받은 견적", ht: "Estimasyon ou, pote sou", it: "Il tuo preventivo, riportato", ar: "تقديرك، مُرحَّل", pl: "Twoja wycena, przeniesiona" },
